$ErrorActionPreference='Stop';$root=Join-Path $PSScriptRoot '..\src\WAID.Desktop';$main=Get-Content -Raw (Join-Path $root 'MainWindow.xaml');@('NavDashboard','NavDrivers','NavBoot','NavUpdates','NavStorage','NavSecurity','NavDiagnosis','NavHealth','NavOperations','NavRepairs','NavHistory','NavAudit','NavPlugins')|ForEach-Object{if($main-notmatch$_){throw "Missing automation id $_"}};$app=Get-Content -Raw (Join-Path $root 'App.xaml.cs');if($app-notmatch'StartupRecoveryTitle'){throw 'Missing startup recovery automation id'};$settings=Get-Content -Raw (Join-Path $root 'Views\SettingsPage.xaml');@('SettingsSearch','ImportSettingsProfile','ExportSettingsProfile','ResetSettings','RefreshDatabaseHealth','BackupDatabase','RestoreDatabase')|ForEach-Object{if($settings-notmatch$_){throw "Missing settings automation id $_"}};$dashboard=Get-Content -Raw (Join-Path $root 'Views\DashboardPage.xaml');if($dashboard-notmatch'ScannerPlan'){throw 'Missing scanner plan automation id'};@('DriverHealthPage.xaml','BootHealthPage.xaml','UpdateHealthPage.xaml','StorageCenterPage.xaml','SecurityCenterPage.xaml')|ForEach-Object{[xml](Get-Content -Raw (Join-Path $root "Views\$_"))|Out-Null};$security=Get-Content -Raw (Join-Path $root 'Views\SecurityCenterPage.xaml');@('SecurityCenterTitle','AnalyzeSecurityButton')|ForEach-Object{if($security-notmatch$_){throw "Missing security accessibility id $_"}};Get-ChildItem (Join-Path $root 'Views') -Filter '*.xaml'|ForEach-Object{[xml](Get-Content -Raw $_.FullName)|Out-Null};Write-Host 'Accessibility navigation and recovery smoke checks passed.'
